using System;
using UnityEngine;

namespace Game.Planes
{
    /// <summary>All planes in hangar order (generated by PlaneBuilder) plus how stats scale the flight model.</summary>
    [CreateAssetMenu(menuName = "Game/Configs/Plane Catalog", fileName = "PlaneCatalog")]
    public sealed class PlaneCatalog : ScriptableObject
    {
        [SerializeField] private PlaneConfig[] _planes = Array.Empty<PlaneConfig>();
        [SerializeField] private PlaneStatScaling _scaling;

        public int Count => _planes.Length;
        public PlaneStatScaling Scaling => _scaling;
        public PlaneConfig Get(int index) => _planes[Mathf.Clamp(index, 0, _planes.Length - 1)];

        public int IndexOf(string id)
        {
            for (var i = 0; i < _planes.Length; i++)
                if (_planes[i] != null && _planes[i].Id == id) return i;
            return -1;
        }

#if UNITY_EDITOR
        public void Define(PlaneConfig[] planes, PlaneStatScaling scaling)
        {
            _planes = planes;
            _scaling = scaling;
        }
#endif
    }
}
